  insert into public.brands (name, website, description, country, status) values ('MAËLYS', 'https://www.maelys.com', 'Science-backed body-care brand (firming, smoothing and toning creams and serums for body concerns at every life stage), sold DTC and at Ulta Beauty. Its affiliate program runs on Awin as ''Maelys Cosmetics USA Inc.'' with commission starting at 15%. No earnings cap statement is published on the fetched Awin profile, so the cap stays unknown.', 'United States', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'beauty'), true);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Awin', 15, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://ui.awin.com/merchant-profile/121648.', 'https://ui.awin.com/merchant-profile/121648', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'MAËLYS Affiliate Program (Awin)', 'https://ui.awin.com/merchant-profile/121648', null, 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://ui.awin.com/merchant-profile/121648', 'affiliate_network', 'affiliate_program', 'MAËLYS'' own Awin merchant profile (Maelys Cosmetics USA Inc.) presents the brand''s body-care range — toning, smoothing, firming and hydrating products, clinically proven and top-selling at Ulta Beauty — and recruits affiliate partners through Awin.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://ui.awin.com/merchant-profile/121648', 'affiliate_network', 'commission_rate', 'The Awin profile states ''Commission starting at 15%'', so 15% is recorded as the starting rate. The profile publishes no earnings cap statement and no absolute creator counts, so commission_cap and creator_saturation stay unknown.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 26, 16, 15, 5, 7, 4, '{"compensation": "Commission starting at 15% on Awin is solid; no cap statement is published, so the cap is honestly unknown.", "contact_access": "No public program email is published; contact runs through the Awin application.", "credibility": "Established DTC body-care brand with Ulta Beauty distribution and clinical-claims positioning.", "niche_fit": "Body-firming and smoothing products are built for before/after and routine UGC, a core beauty format.", "opportunity_availability": "Open application through Awin, subject to network approval.", "ugc_evidence": "A creator-led brand whose Awin profile recruits partners with media-ready products and regularly updated promotional materials."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('NIRA', 'https://www.niraskin.com', 'At-home skincare laser brand (NIRA Precision and Pro lasers plus hyaluronic acid serum) for wrinkle reduction. Its own Affiliate Program page recruits beauty influencers, bloggers and estheticians, routes applications through ShopMy, and offers a free laser and unique discount code. Published rates conflict — older Refersion-era reports say 10% while a 2026 Katalys/Impact listing shows 8% — so commission_rate is recorded as null. No cap statement is published.', 'United States', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'skincare'), true);
  insert into public.brand_contacts (brand_id, contact_type, email, contact_url, source_url, verification_status, last_verified_at) values (bid, 'partnerships', 'partners@niraskin.com', null, null, 'needs_review', null);
  insert into public.brand_contacts (brand_id, contact_type, email, contact_url, source_url, verification_status, last_verified_at) values (bid, 'general', 'info@niraskin.com', null, null, 'needs_review', null);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'ShopMy', null, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://www.niraskin.com/pages/affiliate-program.', 'https://www.niraskin.com/pages/affiliate-program', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'NIRA Affiliate Program (ShopMy)', 'https://www.niraskin.com/pages/affiliate-program', null, 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.niraskin.com/pages/affiliate-program', 'brand_site', 'affiliate_program', 'NIRA''s own Affiliate Program page invites beauty influencers, beauty bloggers/YouTubers, beauty experts and estheticians to join the #NIRATribe: earn commission on sales generated, give followers a unique discount code, receive a free NIRA laser and serum, and get training, support and social features. The Apply Now route goes through ShopMy. The page publishes the contact email info@niraskin.com.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://loriballen.com/nira-affiliate-program/', 'affiliate_directory', 'commission_rate', 'An affiliate write-up of the program reports a 10% commission via the Refersion network with a unique audience discount code, and a creator blog review from the same era likewise reports 10% on the $399 device.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.glp1drugs.org/l/nira-review', 'affiliate_directory', 'commission_rate', 'A 2026 review discloses earning 8% on NIRA orders and cites a Katalys offer listing (sub-network Impact) at 8.00% commission. That conflicts with the older 10% Refersion-era reports, and NIRA''s own current program page publishes no rate, so commission_rate is recorded as null rather than guessed. The brand''s own affiliate blog publishes partners@niraskin.com for affiliate questions. No source publishes an earnings cap statement or absolute creator counts, so commission_cap and creator_saturation stay unknown.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 25, 16, 7, 12, 7, 4, '{"compensation": "Published rates conflict (10% older vs 8% in a 2026 listing) and the brand''s own page publishes none, so the rate is null and compensation scored down; cap unknown.", "contact_access": "Two published emails \u2014 partners@niraskin.com for affiliates and info@niraskin.com on the program page \u2014 plus phone numbers.", "credibility": "Established device brand with a long-running affiliate operation and high price points ($449\u2013$1,049 devices in a 2026 review); rate documentation is the weak point.", "niche_fit": "At-home laser devices are premium, demonstrable skincare-tech products made for long-form review and results UGC.", "opportunity_availability": "Publicly open to apply via the brand''s page through ShopMy, aimed at influencers, bloggers and estheticians.", "ugc_evidence": "A mature creator program: free device, unique codes, launch access, training, giveaways and a brand-run affiliate blog coaching creators per platform."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Sonia Roselli Beauty', 'https://www.soniaroselli.com', 'Makeup-artist-founded skincare and skin-prep brand. Its own Brand Ambassador Program page runs through LTK and GOAFF Pro: ambassadors start at 5% commission and top performers can earn up to 20%, with product perks and feature opportunities, and no giant following required. The 5% starting tier is recorded as the rate. No cap statement is published.', 'United States', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'skincare'), true);
  insert into public.brand_contacts (brand_id, contact_type, email, contact_url, source_url, verification_status, last_verified_at) values (bid, 'general', 'support@soniaroselli.com', null, null, 'needs_review', null);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'GOAFF Pro / LTK', 5, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://www.soniaroselli.com/pages/brand-ambassadors.', 'https://www.soniaroselli.com/pages/brand-ambassadors', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Sonia Roselli Beauty Brand Ambassador Program', 'https://www.soniaroselli.com/pages/brand-ambassadors', null, 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.soniaroselli.com/pages/brand-ambassadors', 'brand_site', 'affiliate_program', 'Sonia Roselli''s own Brand Ambassador Program page (''Let''s Make Money Together'') recruits skincare and beauty content creators, estheticians, makeup artists and loyal customers — ''No giant following required'' — with commission, product perks for active ambassadors and possible features on brand channels. The program runs through two affiliate platforms: LTK (LikeToKnow.it) and GOAFF Pro.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.soniaroselli.com/pages/brand-ambassadors', 'brand_site', 'commission_rate', 'The brand''s own page states ambassadors ''Start at 5% commission'' and ''Top performers can earn up to 20%'', tiered 5–20% by sales performance per platform, U.S. ambassadors only. The 5% starting tier is recorded as the rate. The page publishes the support email support@soniaroselli.com. No source publishes an earnings cap statement or absolute creator counts, so commission_cap and creator_saturation stay unknown.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 23, 15, 11, 9, 8, 4, '{"compensation": "5% starting commission is modest but tiers to 20% for top performers; no cap statement is published, so the cap is honestly unknown.", "contact_access": "A support email is published on the brand''s own site alongside the ambassador application routes.", "credibility": "Established makeup-artist-founded brand with a full storefront and social presence across Instagram, TikTok and YouTube.", "niche_fit": "Skin-prep and pro-artist skincare is strong material for tutorial and routine UGC.", "opportunity_availability": "Open application via LTK or GOAFF Pro; U.S. ambassadors only.", "ugc_evidence": "A creator-facing ambassador program on two platforms with product perks, features and an explicit no-giant-following stance."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Tina Pearson Beauty', 'https://shoptinapearson.com', 'Curly and textured-hair care brand tied to the Tina Pearson salon in Edgewater, NJ. Its own Brand Ambassador Program page pays 15% commission on every product sale through a unique affiliate link with real-time dashboard tracking and monthly payouts, plus a 15% follower discount code and free salon sessions. Ambassadors need 1,500+ combined followers and one content post a month. No cap statement is published.', 'United States', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'beauty'), true);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Brand direct (Tina Pearson Brand Ambassador Program)', 15, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://shoptinapearson.com/pages/tina-pearson-brand-ambassador-program.', 'https://shoptinapearson.com/pages/tina-pearson-brand-ambassador-program', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Tina Pearson Brand Ambassador Program', 'https://shoptinapearson.com/pages/tina-pearson-brand-ambassador-program', null, 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://shoptinapearson.com/pages/tina-pearson-brand-ambassador-program', 'brand_site', 'affiliate_program', 'Tina Pearson''s own ambassador page recruits beauty and fashion content creators and hair stylists to share their curl/textured-hair journey: free Curl It or Silk It salon session first, then a free session after every three new salon referrals, early access to launches and community perks. Requirements: 1,500+ followers combined, consistent posting, one piece of content per month.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://shoptinapearson.com/pages/tina-pearson-brand-ambassador-program', 'brand_site', 'commission_rate', 'The brand''s own page states ''Earn 15% commission on every product sale made through your unique affiliate link'', with real-time tracking through an affiliate dashboard, monthly payouts, and a unique 15%-off code for followers. No source publishes an earnings cap statement or absolute creator counts, so commission_cap and creator_saturation stay unknown.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 22, 16, 15, 5, 7, 3, '{"compensation": "15% on every product sale with monthly payouts is a strong published rate; cap unknown.", "contact_access": "No public program email is published; application runs through the brand''s own page form.", "credibility": "Small salon-led brand with a real storefront and physical salon; limited track record beyond its local base.", "niche_fit": "Textured-hair regimens and salon transformations are high-engagement hair UGC, though the niche is specific.", "opportunity_availability": "Open application with a modest 1,500+ combined-follower requirement.", "ugc_evidence": "A structured ambassador program built around monthly content, before/after salon content, tagging and code-in-caption rules."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Doré', 'https://wearedore.com', 'French-inspired minimalist skincare brand launched in 2022 by Garance Doré and Emily Yeston. Its Become an Ambassador page (served on the brand''s preview subdomain, flagged needs_review) offers commission on referrals, run through Superfiliate; a creator-program roundup that checked the brand''s own page records 10% commission, product gifting and a community discount, with no follower minimum and creators accepted worldwide. That 10% is recorded as the rate. No cap statement is published.', 'United States', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'skincare'), true);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Superfiliate', 10, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://preview.wearedore.com/pages/ambassador.', 'https://preview.wearedore.com/pages/ambassador', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Doré Ambassador Program (Superfiliate)', 'https://preview.wearedore.com/pages/ambassador', null, 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://preview.wearedore.com/pages/ambassador', 'brand_site', 'affiliate_program', 'Doré''s Become an Ambassador page — fetched on the brand''s preview subdomain, so flagged needs_review — presents the French-inspired skincare brand and states: ''As a Doré Ambassador, you will have the opportunity to share Doré with your community while earning a commission on any referrals.'' The page''s FAQ answers sit behind toggles the fetch could not expand.', 'needs_review', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.creatorsjet.com/blog/brands-with-ambassador-programs', 'affiliate_directory', 'commission_rate', 'A creator-program roundup describing Doré''s own ambassador page records the program as run through Superfiliate, paying 10% commission on sales through the referral link, with product gifting, a community discount and early access; applicants must be 18+ and Doré welcomes creators from any country. A Sovrn Commerce merchant listing for Doré exists but could not verify a rate. No source publishes an earnings cap statement or absolute creator counts, so commission_cap and creator_saturation stay unknown.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 13, 12, 5, 8, 4, '{"compensation": "10% commission is mid-range and rests on a roundup''s reading of the brand page rather than a rate published in fetched page text; cap unknown.", "contact_access": "No public program email is published; access runs through the ambassador application.", "credibility": "Known founder-led brand launched in 2022 with retail and press presence; program documentation is thin.", "niche_fit": "Minimalist French skincare routines are premium, highly shareable skincare UGC material.", "opportunity_availability": "No follower minimum reported and creators accepted worldwide.", "ugc_evidence": "A brand-run ambassador program with gifting, referral commission and early access, though the program page is thin and served on a preview subdomain."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('ASASA', 'https://asasa.eu', 'European online cosmetics store selling branded beauty products. Its own Affiliate Program page pays 10% commission on all sales made through a referral link with a personal code, with weekly payouts and a personal dashboard — and states ''Opportunity for fast and unlimited earnings'', so commission_cap is recorded as verified uncapped. Top affiliates receive free products monthly and can buy at distributor prices (about 40% off) for promotional use.', 'European Union', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'beauty'), true);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Brand direct (ASASA Affiliate Program)', 10, 'Commission cap: UNCAPPED — stated in the program terms (see evidence). Creator saturation: unknown (see evidence). Rate as reported by https://asasa.eu/affiliate-program/.', 'https://asasa.eu/affiliate-program/', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'ASASA Affiliate Program', 'https://asasa.eu/affiliate-program/', null, 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://asasa.eu/affiliate-program/', 'brand_site', 'affiliate_program', 'ASASA''s own Affiliate Program page recruits people with social media presence who love sharing products: a unique affiliate identification code, a personal dashboard to track stats, sales and commissions, weekly payout of earned commissions, creative freedom and long-term partnership potential.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://asasa.eu/affiliate-program/', 'brand_site', 'commission_cap', 'The brand''s own page publishes ''10% commission on all sales made through our online store using a referral link with a personal identification code'' and, in the same benefits list, ''Opportunity for fast and unlimited earnings'' — an explicit unlimited-earnings statement, so commission_cap is recorded as uncapped. The page also offers top affiliates 4 free products per month and distributor-price purchasing (about 40% off) for promotional or personal use. No absolute creator counts are published, so creator_saturation stays unknown.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 20, 12, 17, 5, 8, 3, '{"compensation": "10% commission with an explicit ''unlimited earnings'' statement on the brand''s own page \u2014 verified uncapped \u2014 plus weekly payouts.", "contact_access": "No public program email is published; application runs through the brand''s own page.", "credibility": "Operating European cosmetics retailer with a detailed program page, but a limited public track record.", "niche_fit": "A multi-brand cosmetics store gives beauty creators a wide product range to feature, though it is a retailer rather than a single product brand.", "opportunity_availability": "Open to applicants with social media presence and a good online reputation.", "ugc_evidence": "A standard own-site affiliate program with codes, dashboard and creative freedom; no creator-specific perks beyond free products for top sellers."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Varia Hair', 'http://variahair.com', 'Human-hair wigs, toppers and extensions brand. Its own affiliate page pays 10% commission on qualifying referred sales with a 30-day tracking window, run through GoAffPro (variahair.goaffpro.com), with ready-to-use marketing materials; high performers may unlock higher rates and campaigns. No cap statement is published — the FAQ''s ''the more you promote, the more you can earn'' is not an earnings-cap statement, so the cap stays unknown.', 'United States', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'beauty'), true);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'GoAffPro', 10, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by http://variahair.com/pages/affiliate-1.', 'http://variahair.com/pages/affiliate-1', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Varia Hair Affiliate Program (GoAffPro)', 'http://variahair.com/pages/affiliate-1', null, 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'http://variahair.com/pages/affiliate-1', 'brand_site', 'affiliate_program', 'Varia Hair''s own affiliate page recruits beauty creators, hairstylists, wig enthusiasts and TikTok/Instagram/YouTube creators: apply, get a unique affiliate link and promo code through its GoAffPro portal, share wigs, toppers and extensions, and earn commission, with ready-to-use product images and creative assets.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'http://variahair.com/pages/affiliate-1', 'brand_site', 'commission_rate', 'The brand''s own page states ''10% Commission — Earn 10% on qualifying referred sales'' with a 30-day tracking window, and notes high-performing affiliates may be eligible for higher rates and exclusive campaigns. Its FAQ answer to ''How Much Can I Earn?'' repeats the 10% and says the more you promote the more you can earn — that is not an explicit no-cap statement, so commission_cap stays unknown. No absolute creator counts are published, so creator_saturation stays unknown.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 21, 14, 12, 5, 8, 3, '{"compensation": "10% per sale is mid-range with possible higher tiers for performers; no cap statement is published, so the cap is honestly unknown.", "contact_access": "No public program email is published; contact runs through the GoAffPro application.", "credibility": "Operating DTC wig brand with worldwide free shipping and a 30-day return guarantee; limited independent track record.", "niche_fit": "Wig try-ons and transformations are proven high-performing beauty UGC formats.", "opportunity_availability": "Open application through the brand''s page into GoAffPro.", "ugc_evidence": "A creator-built program with ready-to-use files, assets and explicit recruitment of TikTok/Instagram/YouTube creators."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('ThePuffCuff', 'https://thepuffcuff.com', 'Maker of the PuffCuff hair clamp for thick, curly and textured hair, sold at Sally Beauty, Amazon and Walmart.com. Its own ambassador program page pays a 10% base commission on sales generated by an ambassador''s code or link, with a 15% follower discount, a SWAG bag and cross-promotion; ambassadors need at least 10,000 followers on Instagram or YouTube and 3%+ engagement. No cap statement is published.', 'United States', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'beauty'), true);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Brand direct (PuffCuff Ambassador Program)', 10, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://thepuffcuff.com/pages/the-pc-male-ambassador-program.', 'https://thepuffcuff.com/pages/the-pc-male-ambassador-program', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'PuffCuff Ambassador Program', 'https://thepuffcuff.com/pages/the-pc-male-ambassador-program', null, 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://thepuffcuff.com/pages/the-pc-male-ambassador-program', 'brand_site', 'affiliate_program', 'ThePuffCuff''s own ambassador program page recruits everyday content creators sharing curly-hair tips and styling tutorials on blogs, Instagram, YouTube and TikTok, and describes the brand''s retail presence (Sally Beauty, Amazon, Walmart.com) and press (Marie Claire, Black Enterprise, Atlanta Journal-Constitution).', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://thepuffcuff.com/pages/the-pc-male-ambassador-program', 'brand_site', 'commission_rate', 'The brand''s own page lists ambassador benefits including ''10% base commission on sales generated by your unique ambassador code or affiliate link'' and a 15% discount for followers, plus a SWAG bag, giveaways and early access. Requirements: at least 10,000 followers on Instagram and/or YouTube and 3%+ engagement. No source publishes an earnings cap statement or absolute creator counts, so commission_cap and creator_saturation stay unknown.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 21, 15, 12, 5, 5, 4, '{"compensation": "10% base commission is mid-range; no cap statement is published, so the cap is honestly unknown.", "contact_access": "No public program email is published; application runs through the linked form on the brand''s page.", "credibility": "Established niche brand with national retail distribution and mainstream press coverage.", "niche_fit": "A single hero styling tool for curly and textured hair maps cleanly onto tutorial and styling UGC.", "opportunity_availability": "Gated: at least 10,000 followers on Instagram or YouTube plus 3%+ engagement required.", "ugc_evidence": "A defined ambassador program with content expectations, takeovers, cross-promotion and giveaways."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Umberto Giannini', 'https://www.umbertogiannini.com', 'UK salon haircare brand. Its own Ambassadors page runs the #HAIRLOVE UG ambassador program — own discount code, product top-ups, first access to launches — describing commission only as ''up to 10% based on performance'', an up-to ceiling with no published base rate, so commission_rate is recorded as null. The same page routes affiliates to the brand''s Awin affiliate program, manually reviewed. No cap statement is published.', 'United Kingdom', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'beauty'), true);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Awin', null, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://www.umbertogiannini.com/pages/ambassadors.', 'https://www.umbertogiannini.com/pages/ambassadors', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Umberto Giannini Affiliate & Ambassador Program (Awin)', 'https://www.umbertogiannini.com/pages/ambassadors', null, 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.umbertogiannini.com/pages/ambassadors', 'brand_site', 'affiliate_program', 'Umberto Giannini''s own Ambassadors page presents the #HAIRLOVE UG ambassador program: own discount code, exposure on brand channels, insider access and events, first to try launches and regular product top-ups, in exchange for genuine content (one video at least every other week, tracked via UTM link). The same page carries an affiliate programme section: ''Apply to our Awin affiliate program and start earning commission with Umberto Giannini'' with manual review by its affiliate team.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.umbertogiannini.com/pages/ambassadors', 'brand_site', 'commission_rate', 'The brand''s own page describes ambassador pay only as ''Earn up to 10% commission on sales based on performance''. An up-to figure is a ceiling, not a base rate, and the Awin listing''s rate is not published on the fetched page, so commission_rate is recorded as null. No source publishes an earnings cap statement or absolute creator counts, so commission_cap and creator_saturation stay unknown.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 23, 14, 7, 5, 7, 4, '{"compensation": "Only an ''up to 10%'' ceiling is published with no base rate, so the rate is null and compensation scored cautiously; cap unknown.", "contact_access": "No public program email is published; contact runs through the ambassador form or Awin.", "credibility": "Long-running UK salon haircare brand with national retail presence.", "niche_fit": "Salon haircare routines and styling content are staple beauty UGC formats.", "opportunity_availability": "Ambassador applications via the brand''s form; affiliate applications via Awin with manual review.", "ugc_evidence": "Two creator routes on one page: a content-led ambassador program with codes and top-ups, plus an Awin affiliate program."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Madison Reed', 'https://www.madison-reed.com', 'At-home hair color brand founded in 2013, also operating Hair Color Bars and selling through Ulta, Sephora and QVC. Its affiliate program is long-running, but published terms conflict across eras and networks — older ShareASale listings quote flat payouts (up to $25 per new-customer order, $5 returning), a roundup quotes 20%, and a structured listing describes Impact-run terms of 20% on booked appointments and 3.5–10% on product sales — so commission_rate is recorded as null with the flat bounties documented. No cap statement is published.', 'United States', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'beauty'), true);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Impact', null, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://healthglowy.com/hair-product-affiliate-programs/.', 'https://www.madison-reed.com/affiliates', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Madison Reed Affiliate Program', 'https://www.madison-reed.com/affiliates', null, 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://affiliateprogramsdir.com/madison-reed-professional-hair-color-affiliate-program-review/', 'affiliate_directory', 'affiliate_program', 'A directory review of Madison Reed''s affiliate program records flat payouts — up to $25 per order for new customers and up to $5 per order for returning customers — a 30-day cookie, a $50 payout threshold and the ShareASale network, plus a $10 bonus for referring approved affiliates. Flat bounties are recorded as flat here; no single % rate is settled.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://healthglowy.com/hair-product-affiliate-programs/', 'affiliate_directory', 'commission_rate', 'A structured hair-program listing instead describes Madison Reed at ''20% (Booked Appointment) | 3.5% to 10% (Product Sales)'' with Impact Radius paying commissions monthly, while another roundup quotes a flat 20% per referred sale. The figures and networks conflict across sources and eras (ShareASale flat bounties vs Impact percentage terms), so commission_rate is recorded as null rather than guessed. No source publishes an earnings cap statement or absolute creator counts, so commission_cap and creator_saturation stay unknown.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 11, 7, 5, 7, 5, '{"compensation": "Published terms conflict across networks and eras (flat bounties vs percentages), so the rate is null and compensation scored down; cap unknown.", "contact_access": "No public program email is published; access runs through the network application.", "credibility": "Established hair-color brand founded in 2013 with national retail, salon locations and QVC/Ulta distribution.", "niche_fit": "At-home hair color and root coverage are highly demonstrable, problem-solution beauty UGC.", "opportunity_availability": "Listed as joinable through its affiliate network routes.", "ugc_evidence": "A long-running affiliate program with tracked links; the brand also works with creators socially, but publishes no creator program page of its own in the fetched sources."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('KICKSOWN', 'https://www.kicksown.com', 'Premium sneaker store whose own affiliate program is built for bloggers, influencers and content creators promoting through YouTube, TikTok, Instagram, blogs or Discord. Its own program page publishes a 3% commission on every successful order and an explicit unlimited-earnings statement - a verified-uncapped program - with a published business contact email for commission and collaboration questions.', 'United States', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'fashion'), true);
  insert into public.brand_contacts (brand_id, contact_type, email, contact_url, source_url, verification_status, last_verified_at) values (bid, 'partnerships', 'cooperation@kicksown.com', null, 'https://www.kicksown.com/pages/join-the-kicksown-affiliate-program-start-earning-today', 'verified', now());
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Brand direct', 3, 'Commission cap: UNCAPPED — stated in the program terms (see evidence). Creator saturation: unknown (see evidence). Rate as reported by https://www.kicksown.com/pages/join-the-kicksown-affiliate-program-start-earning-today.', 'https://kicksown.goaffpro.com', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'KICKSOWN Affiliate Program', 'https://kicksown.goaffpro.com', 'https://www.kicksown.com/pages/join-the-kicksown-affiliate-program-start-earning-today', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.kicksown.com/pages/join-the-kicksown-affiliate-program-start-earning-today', 'official_program_page', 'commission_cap', 'The brand''s own affiliate page, under ''Why Join KICKSOWN?'': ''Unlimited Earnings: No earning cap. The more you share, the more you earn.'' - an explicit no-cap earnings statement on the brand''s own program page, so commission_cap is uncapped.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.kicksown.com/pages/join-the-kicksown-affiliate-program-start-earning-today', 'official_program_page', 'commission_rate', 'The same page: ''Earn 3% Commission - Receive a 3% commission on every successful order made through your referral link.'' Qualified influencers may receive free products and additional collaboration opportunities; commissions are processed at the end of every month with a $50 USD minimum payout, and the page publishes the contact cooperation@kicksown.com for commission or collaboration questions.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 23, 15, 10, 12, 8, 3, '{"compensation": "Verified-uncapped earnings on the brand''s own page, but the rate itself is low at 3% per order, with a $50 minimum payout - the no-cap statement is explicit, the percentage is not generous.", "contact_access": "The program page publishes a named business contact for commissions and collaborations (cooperation@kicksown.com), plus support and feedback emails, a phone number and a street address - unusually direct access.", "credibility": "A small specialist sneaker store rather than an established footwear name, though its program page is detailed and current, with a real affiliate app and published payout terms.", "niche_fit": "Premium and performance sneakers are core sneakerhead and streetwear content - reviews, on-feet videos, styling and release coverage across TikTok, Instagram and YouTube.", "opportunity_availability": "Open sign-up through the brand''s affiliate portal and mobile app, aimed at bloggers, influencers and content creators.", "ugc_evidence": "A creator-first program by design: it recruits influencers and content creators by name, names TikTok, Instagram and YouTube as promotion channels, and offers qualified influencers free products and review collaborations."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Mova99', 'https://www.mova99.com', 'New multi-category DTC store (fashion items and accessories feature throughout its program examples) whose Creator Program launched with an effective date of June 22, 2026. Its own program page publishes a flat 10% commission on every sale with an explicit no-cap-on-earnings statement - a verified-uncapped program - no minimum follower requirement, a free first product for approved affiliates, and bonus commission tiers for top performers.', 'United States', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'fashion'), true);
  insert into public.brand_contacts (brand_id, contact_type, email, contact_url, source_url, verification_status, last_verified_at) values (bid, 'general', 'support@mova99.com', null, 'https://www.mova99.com/02_affiliate_influencer_program', 'verified', now());
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Brand direct', 10, 'Commission cap: UNCAPPED — stated in the program terms (see evidence). Creator saturation: unknown (see evidence). Rate as reported by https://www.mova99.com/02_affiliate_influencer_program.', 'https://www.mova99.com/02_affiliate_influencer_program', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Mova99 Creator Program (Affiliate & Influencer Program)', 'https://www.mova99.com/02_affiliate_influencer_program', 'https://www.mova99.com/02_affiliate_influencer_program', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.mova99.com/02_affiliate_influencer_program', 'official_program_page', 'commission_cap', 'The brand''s own program page (Mova99 LLC, effective June 22, 2026) states in its commission structure ''The more you share, the more you earn - with no cap'', and its FAQ answers ''How much do I earn per sale?'' with ''You earn a flat 10% commission on every qualifying order placed through your referral link - with no cap on earnings.'' An explicit no-cap earnings statement in the brand''s own program terms, so commission_cap is uncapped.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.mova99.com/02_affiliate_influencer_program', 'official_program_page', 'creator_program', 'The same page: ''There are no minimum follower requirements to join. Anyone can apply'', with most applications reviewed within 24 hours; new affiliates receive 1 free product of their choice upon approval to create a first review; a Creator Bonus Program adds +2% to +5% bonus commission at monthly sales thresholds; tracking is a 30-day cookie with last-click attribution; and questions go to support@mova99.com. No absolute creator-count evidence is published, so creator_saturation stays unknown - a new program page alone is not a creator count.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 20, 16, 15, 8, 9, 2, '{"compensation": "A brand-published flat 10% on every sale with an explicit no-cap-on-earnings statement - verified uncapped - plus +2% to +5% bonus tiers for top performers and no minimum payout amount.", "contact_access": "A published support email (support@mova99.com) with a stated 24-hour response time and an affiliate manager route for free-product requests; no dedicated partnerships inbox is published.", "credibility": "A very new, small multi-category store (program effective June 2026) with no established brand track record - the program terms are detailed, but the business itself is unproven, so credibility scores low.", "niche_fit": "Fashion items and accessories anchor the program''s own examples (styling content for fashion/accessories is a named content category), though the store is multi-category rather than a pure fashion brand.", "opportunity_availability": "No minimum follower requirement, anyone can apply, most applications reviewed within 24 hours, and a free product on approval - the most open door in this round.", "ugc_evidence": "A program built specifically for creators and influencers: named content categories (unboxings, styling, before/after, comparisons), free products for content creation, and promotion explicitly across TikTok, Instagram and YouTube."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Styled', 'https://styled.shop', 'Occasionwear store - evening gowns, prom and wedding-guest dresses, plus jewellery and watches - whose own affiliate program pays creators 20% on every order through their link or code, with ready-made model photography provided so creators can post without buying product first. Its own fetched program page publishes no earnings-cap statement, so the cap is honestly unknown.', null, 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'fashion'), true);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Brand direct', 20, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://styled.shop/pages/affiliate-program.', 'https://styled.goaffpro.com', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Styled Affiliate Program', 'https://styled.goaffpro.com', 'https://styled.shop/pages/affiliate-program', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://styled.shop/pages/affiliate-program', 'official_program_page', 'creator_program', 'The brand''s own affiliate page: ''You earn 20% on every order that comes through your link or code. Not a one-time bonus - every single sale'', with followers getting 10% off, monthly payouts to PayPal or bank, ''0 follower minimum'' and ''No product needed to start''. The same 20% and follower discount apply to every ring, bracelet, chain, earring and watch in the store. No earnings-cap statement appears on the fetched page, so commission_cap is unknown.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://styled.shop/pages/affiliate-program', 'official_program_page', 'ugc_evidence', 'The page names its audience precisely: ''Pinterest creators with prom, wedding guest or evening wear boards'', ''Instagram and TikTok creators who post get ready with me, fit checks or event looks'', bloggers and Facebook group admins; it states ''Small accounts with engaged followers often sell more than big ones'', supplies model shots of every gown from four angles for Pins, posts and Stories, and confirms creators from any country can join with worldwide shipping.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 16, 17, 4, 9, 2, '{"compensation": "A brand-published 20% commission on every sale - among the strongest rates in this round - with a 10% follower discount to help conversion and monthly PayPal or bank payouts. No cap statement is published on the fetched page.", "contact_access": "No partnerships email is published on the fetched page - application is through the brand''s affiliate portal.", "credibility": "A young direct-to-consumer occasionwear store with a thin public footprint compared with established fashion names; its program page is detailed and creator-specific, but the brand itself is unproven at scale.", "niche_fit": "Evening gowns, prom and wedding-guest dresses plus jewellery and watches are pure occasion-fashion content - GRWM, fit checks, dress roundups and event looks.", "opportunity_availability": "Free to join with a zero follower minimum, no product purchase needed, and creators from any country accepted.", "ugc_evidence": "One of the most creator-specific program pages in this round: named creator types per platform, ready-made photography for posts, and an explicit welcome for small accounts."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Patagonia', 'https://www.patagonia.com', 'Iconic outdoor clothing and gear brand founded in 1973, built around climbing, hiking, skiing, surfing and trail running. Its own affiliate page publishes an 8% base commission for content publishers, a dedicated affiliate manager, and a quick application process through Impact.', 'United States', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'travel'), true);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Impact', 8, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://www.patagonia.com/affiliates.html.', 'https://www.patagonia.com/affiliates.html', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Patagonia Affiliate Program (Impact)', 'https://www.patagonia.com/affiliates.html', 'https://www.patagonia.com/affiliates.html', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.patagonia.com/affiliates.html', 'official_program_page', 'affiliate_program', 'The brand''s own affiliate page lists Partner Benefits verbatim: ''8% base commission for content publishers'', ''Category-specific banners and text ads'', ''Automated product feed'', ''Dedicated Patagonia affiliate manager'' and ''Quick and easy application process through Impact'', with an Apply Here route into Impact. The brand says it is ''interested in teaming up with creative websites and businesses that share our passion for adventure and environmental stewardship''. No earnings-cap statement is published, so commission_cap is unknown.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 27, 13, 14, 6, 8, 5, '{"compensation": "An official 8% base commission for content publishers on premium-priced outdoor apparel and gear, with a dedicated affiliate manager - a strong, brand-confirmed rate for the category. No cap statement is published.", "contact_access": "A dedicated affiliate manager is promised on the brand''s own page, but no partnerships email is published there - joining is through the Impact application.", "credibility": "One of the most recognised and trusted outdoor brands in the world, founded in 1973, with a decades-long environmental record.", "niche_fit": "Outdoor clothing and gear for climbing, hiking, skiing, surfing and trail running sit at the centre of travel and adventure creator content - gear lists, trip films and field reviews.", "opportunity_availability": "Quick and easy application through Impact per the brand''s own page, with brand review of partner fit.", "ugc_evidence": "The program is framed for creative websites and content publishers, with category-specific creative and an automated product feed; a conventional network program rather than a structured UGC track, but explicitly publisher-facing."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Marmot', 'https://www.marmot.com', 'Outdoor brand founded in 1974 - high-performance clothing, tents, sleeping bags and backpacks for hiking, camping, skiing and climbing. Its own affiliate page publishes an 8% commission on valid sales tracked through CJ Affiliate, with no charge to participate and no minimum sale requirements.', 'United States', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'travel'), true);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'CJ Affiliate', 8, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://www.marmot.com/affiliate-program.html.', 'https://www.marmot.com/affiliate-program.html', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Marmot Affiliate Program (CJ Affiliate)', 'https://www.marmot.com/affiliate-program.html', 'https://www.marmot.com/affiliate-program.html', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.marmot.com/affiliate-program.html', 'official_program_page', 'affiliate_program', 'The brand''s own affiliate page: ''Affiliate Commission Structure - 8% on valid sales'', ''All sales are tracked through our neutral third party affiliate network CJ Affiliate'', payout ''on or around the 20th of the month'', and the FAQ ''What will it cost? Let us put this as clearly as possible: Nothing. There is no charge to participate in the Marmot Affiliate Program and no minimum sale requirements.'' Anyone may submit an application; Marmot reviews each site. No earnings-cap statement is published, so commission_cap is unknown. The page''s Contact Us email is obfuscated in the fetched text, so no email is recorded.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.travelpayouts.com/blog/best-outdoor-affiliate-programs/', 'third_party_directory', 'affiliate_program', 'Travelpayouts'' outdoor program comparison independently lists Marmot at 8% commission via CJ, agreeing with the brand''s own published structure, and several camping roundups report a 90-day cookie for the CJ program; a FlexOffers syndication listing shows a lower 2.4%, which is a reseller feed figure and does not displace the brand''s own 8%.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 25, 11, 14, 5, 8, 5, '{"compensation": "A brand-published 8% on valid sales through CJ, independently agreed by outdoor program comparisons - a solid rate on technical gear with high order values. No cap statement is published.", "contact_access": "The brand''s page routes questions to its Affiliate Network Manager, but the email is obfuscated in the fetched page, so no contact is recorded; joining is through CJ.", "credibility": "A leader in technical outdoor gear since 1974, with the program run through CJ Affiliate''s established tracking and payments.", "niche_fit": "Jackets, tents, sleeping bags and packs are staple hiking, camping and mountain-travel content - kit reviews, camp setups and weather tests.", "opportunity_availability": "Anyone may submit an application through CJ with a live site; no participation charge and no minimum sale requirements, though Marmot reviews each site.", "ugc_evidence": "A conventional network affiliate program with supplied banners, logos and link tools aimed at outdoor publishers; no dedicated creator track is evidenced on the fetched page."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Clench Fitness', 'https://clenchfitness.com', 'Resistance-training equipment brand from New Richmond, Wisconsin - band handles, 41-inch loop resistance bands and footplates built to make strength training accessible without bulky gym equipment. Its own Refersion affiliate portal publishes a referral rate of 20% of revenue (excluding shipping and taxes) on sales within a 30-day cookie, paid on the 1st of each month.', 'United States', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'fitness'), true);
  insert into public.brand_contacts (brand_id, contact_type, email, contact_url, source_url, verification_status, last_verified_at) values (bid, 'general', 'info@clenchfitness.com', null, 'https://www.crunchbase.com/organization/clench-fitness', 'needs_review', null);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Refersion', 20, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://clenchfitness.refersion.com/.', 'https://clenchfitness.refersion.com/', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Clench Fitness Affiliate Program (Refersion)', 'https://clenchfitness.refersion.com/', 'https://clenchfitness.refersion.com/', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://clenchfitness.refersion.com/', 'official_program_page', 'affiliate_program', 'The brand''s own Refersion affiliate portal: ''As an Clench Fitness affiliate, you earn based on your referral sales during a revolving 30 Day Period... Referral Rate = 20% of Revenue (excludes shipping and taxes)'', with its worked example ''You refer a sale that is $117 total but taxes were $7 and shipping was $10. You Earn: 20% on sales of $100 = $20'', a 30-day referral cookie, and ''Payments of commissions are paid on the 1st of each Month for the previous month.'' No earnings-cap statement is published, so commission_cap is unknown.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.Refersion.com/blog/top-fitness-equipment-affiliate-programs/', 'third_party_directory', 'affiliate_program', 'Refersion''s own fitness-equipment roundup independently lists Clench Fitness at ''20% commission'', ''Cookie days: 30'' and ''AOV: $155'', agreeing with the brand''s portal terms, and describes its band handles, loop bands and footplate line for home and travel training.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 14, 18, 6, 7, 3, '{"compensation": "A brand-published 20% of revenue on referred sales - the strongest verified rate among this round''s fitness entries - on a $155 average order value per Refersion''s roundup. No cap statement is published.", "contact_access": "A published company contact email (info@clenchfitness.com) plus application review through the brand''s Refersion portal; no dedicated partnerships inbox is published.", "credibility": "A small specialist equipment maker (Wisconsin-based, small team) rather than a national fitness brand, though its program terms are published in full on its own portal.", "niche_fit": "Resistance bands and handles are home-workout, travel-training and apartment-gym staples - exactly the equipment fitness creators demo daily.", "opportunity_availability": "Online application through the brand''s Refersion portal with brand review; the brand may reject unsuitable sites at its discretion.", "ugc_evidence": "The portal is written for affiliates promoting through ''your site, blog, or social media outlets'', and Refersion''s roundup positions the brand for home-fitness creators - a genuine creator route, though not a structured UGC campaign track."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Hyperlite Mountain Gear', 'https://hyperlitemountaingear.com', 'Ultralight backpacking brand founded in 2009 - Dyneema backpacks, shelters and packs with a cult following among thru-hikers. Its affiliate program runs on AvantLink at a 10% commission with a 30-day cookie and an average order value around $350, agreed across multiple independent program directories.', 'United States', 'published') returning id into bid;
