  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://getlasso.co/affiliate/hyperlite-mountain-gear/', 'third_party_directory', 'affiliate_program', 'Lasso''s program listing reports Hyperlite Mountain Gear at ''10% Per Sale'' with a ''30 Days'' cookie. No earnings-cap statement is published in the fetched sources, so commission_cap is unknown.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.nichepursuits.com/outdoor-affiliate-programs/', 'third_party_directory', 'affiliate_program', 'NichePursuits'' outdoor roundup independently agrees: ''Commission Rate: from 10%'', ''AOV: $350'', ''Cookie Duration: 30 days'', ''Affiliate Program Platform: AvantLink'', and Travelpayouts'' outdoor comparison also lists Hyperlite Mountain Gear at 10% - three directories agree on the rate and network, so 10% via AvantLink is recorded.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 25, 11, 16, 4, 7, 4, '{"compensation": "10% commission on an average order value around $350 - roughly $35 per referred sale, unusually strong per-sale economics for hiking gear. No cap statement is published.", "contact_access": "No partnerships email is published in the fetched sources - joining is through the AvantLink application, with a dedicated affiliate manager reported after approval.", "credibility": "The defining ultralight brand among thru-hikers, founded in 2009, with a focused premium product line and an established network program.", "niche_fit": "Ultralight packs and shelters are core thru-hiking and backpacking content - base-weight breakdowns, gear shakedowns and long-trail films.", "opportunity_availability": "Application through AvantLink with brand approval.", "ugc_evidence": "A conventional network affiliate program aimed at outdoor publishers and reviewers; no structured UGC track is evidenced in the fetched sources."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Yune Yoga', 'https://yuneyoga.com', 'Eco-minded yoga brand - design-led natural rubber, eco and foldable travel mats, towels and straps, featured in national media. Its own affiliate page offers 20% commissions with custom creatives and quick assistance, and its program runs on Refersion; a Refersion roundup''s higher 30% figure is documented as a dissenting claim, with the brand''s own page governing.', 'United States', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'fitness'), true);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Refersion', 20, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://yuneyoga.com/pages/affiliate-program.', 'https://yuneyoga.com/pages/affiliate-program', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Yune Yoga Affiliate Program (Refersion)', 'https://yuneyoga.com/pages/affiliate-program', 'https://yuneyoga.com/pages/affiliate-program', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://yuneyoga.com/pages/affiliate-program', 'official_program_page', 'affiliate_program', 'The brand''s own affiliate page: ''If you would like to be considered for our affiliate program, please fill out the form below. We offer quick assistance on any needs, custom creatives, 20% commissions.'' The brand-published 20% is the recorded rate. No earnings-cap statement is published, so commission_cap is unknown.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.Refersion.com/blog/top-fitness-equipment-affiliate-programs/', 'third_party_directory', 'commission_rate_conflict', 'Refersion''s own fitness-equipment roundup claims 30% commission with a 90-day cookie and $71 AOV for Yune Yoga, which conflicts with the 20% on the brand''s own affiliate page; network listings (affi.io) show the Yune Yoga program on Refersion as opened at 20% revenue with a 90-day cookie, agreeing with the brand''s page. The brand''s own published figure governs and is recorded, with the platform roundup''s 30% noted here as the dissenting figure.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 22, 13, 17, 4, 7, 3, '{"compensation": "A brand-published 20% commission - a top rate for yoga gear - with a 90-day cookie reported on network listings; Refersion''s roundup claims 30%, documented as a dissenting figure in evidence. No cap statement is published.", "contact_access": "Application is a form on the brand''s own affiliate page with ''quick assistance'' promised; no partnerships email is published on the fetched page.", "credibility": "A niche eco yoga brand with national media mentions (New York Times, Women''s Health, Yoga Journal, Conde Nast Traveler per its coverage), but a small operation next to the major activewear names.", "niche_fit": "Artist-designed yoga mats and travel foldable mats map directly to yoga, mobility and home-practice creator content - flows, mat reviews and travel practice setups.", "opportunity_availability": "Application form on the brand''s own page with consideration by the brand; program listed as open on Refersion.", "ugc_evidence": "The brand recruits affiliates with custom creatives and speaks to studios and instructors sharing with followers on social media - a genuine creator route, though without a structured UGC campaign layer."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Trtl', 'https://trtltravel.com', 'Travel-comfort brand behind the Trtl Pillow - the mechanically engineered travel pillow - plus sleep masks, compression socks and travel accessories. Its own affiliate terms confirm a program powered by Social Snowball with referral codes and links and a content usage-rights licence for affiliates, but the brand publishes no commission rate in its terms and directory figures conflict, so no rate is recorded.', null, 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'travel'), true);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Social Snowball', null, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://trtltravel.com/pages/affiliate-marketing-program-terms-and-conditions-for-trtl-travel.', 'https://trtltravel.com/pages/affiliate-marketing-program-terms-and-conditions-for-trtl-travel', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Trtl Affiliate Marketing Program (Social Snowball)', 'https://trtltravel.com/pages/affiliate-marketing-program-terms-and-conditions-for-trtl-travel', 'https://trtltravel.com/pages/affiliate-marketing-program-terms-and-conditions-for-trtl-travel', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://trtltravel.com/pages/affiliate-marketing-program-terms-and-conditions-for-trtl-travel', 'official_program_page', 'creator_program', 'The brand''s own Affiliate Marketing Program Terms: ''Welcome to the Trtl Travel Affiliate Marketing Program, powered by Social Snowball... Affiliates will receive a unique referral code and/or link to share with potential new customers. Commissions are earned on qualifying sales that are directly attributable to the affiliate''s referral code or link.'' The terms set no percentage (''Commission rates are subject to change at Trtl''s discretion'') and grant Trtl a licence to use affiliate content for organic and paid advertising including on Meta and TikTok. No earnings-cap statement is published, so commission_cap is unknown.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://getlasso.co/affiliate/trtl/', 'third_party_directory', 'commission_rate_conflict', 'Published rates conflict: Lasso lists Trtl at ''Up to 22.5%'' with a 14-day cookie, while Shopper''s partnership listing and InfluencerRate both report 5-10%. Because the brand''s own terms publish no rate and the directories disagree, commission_rate is null.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 14, 9, 4, 7, 4, '{"compensation": "No rate is recorded: the brand''s own terms publish no percentage and directory figures conflict (up to 22.5% versus 5-10%), so compensation scores cautiously despite the brand''s strong product price points. No cap statement is published.", "contact_access": "No partnerships email is published in the fetched sources - joining is through the brand''s site and its Social Snowball program.", "credibility": "A well-known single-product-led travel brand - the Trtl Pillow is a category-defining travel accessory sold worldwide.", "niche_fit": "Travel pillows, sleep masks and compression socks are demo-friendly flight and travel-hack content - long-haul comfort tests are a proven creator format.", "opportunity_availability": "Open application via the brand''s program with approval at the brand''s discretion, per its own terms (applicants must be 18+ with a valid payment method).", "ugc_evidence": "A creator-native program structure: referral codes and links via Social Snowball and an explicit content usage-rights licence covering affiliate content on Meta and TikTok - the brand is set up to reuse creator content in paid and organic channels."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Thursday Boot Company', 'https://thursdayboots.com', 'New York direct-to-consumer footwear brand - boots built with the durability of a work boot and the sophistication of a dress boot, plus shoes, jackets and accessories for men and women. Its affiliate program runs on CJ Affiliate; the only published rate found is a single March 2024 directory listing at 4.5% per sale, recorded in evidence but held out of the rate field as a lone dated figure.', 'United States', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'fashion'), true);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'CJ Affiliate', null, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://linkclicky.com/affiliate-program/thursday-boot-company/.', 'https://linkclicky.com/affiliate-program/thursday-boot-company/', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Thursday Boot Company Affiliate Program (CJ Affiliate)', 'https://linkclicky.com/affiliate-program/thursday-boot-company/', 'https://linkclicky.com/affiliate-program/thursday-boot-company/', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://linkclicky.com/affiliate-program/thursday-boot-company/', 'third_party_directory', 'affiliate_program', 'LinkClicky''s program listing (last updated March 11, 2024) reports: Affiliate Platform ''CJ Affiliate'', ''Commission: 4.5% per sale'' for Thursday Boot Company. It is the only published rate found and it is dated, so it is documented here rather than recorded as the current rate - commission_rate is null. No earnings-cap statement is published, so commission_cap is unknown.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://junction.cj.com/article/new-advertisers-launched-in-q3-of-2023', 'network_profile', 'affiliate_program', 'CJ''s own Junction blog lists Thursday Boot Company among the new advertisers launched on the CJ network in Q3 2023, independently corroborating that the brand''s affiliate program runs on CJ Affiliate.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 23, 10, 9, 4, 6, 4, '{"compensation": "The only published figure found is 4.5% per sale from a single March 2024 directory listing - modest and dated, so no rate is recorded and compensation scores cautiously, despite premium boot price points. No cap statement is published.", "contact_access": "No partnerships email is published in the fetched sources - joining is through the CJ application.", "credibility": "An established New York DTC footwear brand with a large social following and national recognition for its boots.", "niche_fit": "Heritage-style boots and leather goods are menswear and fashion staples - outfit builds, boot reviews and break-in diaries are steady creator formats.", "opportunity_availability": "Apply through CJ Affiliate with brand approval; the program''s presence on CJ is corroborated by CJ''s own launch announcement.", "ugc_evidence": "A conventional network affiliate program; the brand''s social presence is creator-heavy, but no structured UGC track is evidenced in the fetched sources."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Cache Coffee & More', 'https://www.cachecoffeeandmore.com', 'Cache Coffee & More is a locally owned coffee shop, cafe and small-batch roastery in Logan, Utah, selling its own roasted coffee direct to consumers, with a brand-direct affiliate program that explicitly recruits content creators, podcasters and social influencers.', 'United States', 'published') returning id into bid;
