  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'brand direct', 10, 'Commission cap: UNCAPPED — stated in the program terms (see evidence). Creator saturation: unknown (see evidence). Rate as reported by https://www.cachecoffeeandmore.com/affiliate.', 'https://www.cachecoffeeandmore.com/affiliate', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Cache Coffee & More Affiliate Program', 'https://www.cachecoffeeandmore.com/affiliate', 'https://www.cachecoffeeandmore.com/affiliate', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.cachecoffeeandmore.com/affiliate', 'brand_website', 'affiliate_program', 'Cache Coffee''s own affiliate page, fetched first-hand, publishes a 10% commission on every referred sale and states the cap explicitly three times: ''No cap'', ''No Earnings Cap'' in the program stats, and the FAQ answer ''10% of every sale your referral link generates. No cap on earnings.'' — so commission_cap is uncapped. The page also publishes a 30-day cookie, free manual-review application, payouts by PayPal, Venmo or bank transfer, and says no large following is needed. No creator-count data is published, so creator_saturation is unknown.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 15, 17, 8, 9, 3, '{"compensation": "10% on every sale with an explicit no-cap statement on the brand''s own page \u2014 verified uncapped.", "contact_access": "Application runs through the brand''s own affiliate page with manual review; no public partnerships email was published on the fetched page.", "credibility": "A real, long-running local roastery and cafe with 463+ verified reviews per its own page, but a small single-location business, which caps credibility.", "niche_fit": "Coffee is an everyday, highly demonstrable product for food, fitness-morning-routine and lifestyle creators; the brand targets patriot, veteran and fitness audiences specifically.", "opportunity_availability": "Program is live and free to apply now from the brand page.", "ugc_evidence": "The brand''s own page explicitly recruits content creators, podcast hosts, YouTube creators and Instagram/TikTok influencers, and says a small engaged audience is enough."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Nootropics Depot', 'https://nootropicsdepot.com', 'Nootropics Depot is a long-running US direct-to-consumer retailer of nootropics and dietary supplements, known for in-house and third-party testing, and runs its own affiliate program under a published affiliate agreement on its website.', 'United States', 'published') returning id into bid;
