  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Nootropics Depot Affiliate Program', 'https://nootropicsdepot.com/affiliates/', 'https://nootropicsdepot.com/affiliates/', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://nootropicsdepot.com/affiliates/', 'brand_terms', 'affiliate_program', 'Nootropics Depot''s own affiliate agreement page, fetched first-hand, publishes the commission structure in section 7.1: 15% on purchases by new customers and 5% on purchases by returning customers, paid via PayPal through a third-party affiliate application. The 15% new-customer rate is recorded. No earnings-cap statement is published in the agreement, so commission_cap is unknown; no creator-count data is published, so creator_saturation is unknown.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 25, 13, 15, 7, 9, 5, '{"compensation": "15% on new customers published in the brand''s own affiliate agreement, dropping to 5% on returning customers; no cap statement, so the cap is unknown.", "contact_access": "Application runs through the brand''s own affiliate agreement page; no public partnerships email was published on the fetched page.", "credibility": "One of the longest-running and most testing-focused nootropics retailers in the US, with full published program terms.", "niche_fit": "A deep nootropic and supplement catalog fits biohacking, productivity, focus and supplement-review creators very well.", "opportunity_availability": "Program is live and joinable now under the published agreement.", "ugc_evidence": "A formal brand-direct affiliate program with a full published agreement, affiliate dashboard and banner creatives."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Safe Catch', 'https://safecatch.com', 'Safe Catch sells premium canned tuna and seafood that it mercury-tests fish by fish, direct to consumers, and runs an affiliate program through Affiliatly with published terms aimed at bloggers and social creators.', 'United States', 'published') returning id into bid;
