  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Safe Catch Affiliate Program', 'https://www.affiliatly.com/af-1069205/affiliate.panel?mode=register', 'https://www.affiliatly.com/af-1069205/affiliate.panel?mode=register', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.affiliatly.com/af-1069205/affiliate.panel?mode=register', 'brand_program_page', 'affiliate_program', 'Safe Catch''s own affiliate program panel (run on Affiliatly), fetched first-hand, publishes a 10% commission on every sale, a 60-day tracking window, tracking by coupon codes and links, an exclusive 10% follower discount, and monthly payouts once $25 is earned. The program''s own terms likewise state a 10% referral fee per product in a qualified transaction. A coupon-site brief mentions a separate 10–15% ambassador range, which is not the recorded route. No earnings-cap statement is published, so commission_cap is unknown; no creator-count data is published, so creator_saturation is unknown.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 23, 14, 13, 7, 9, 4, '{"compensation": "10% on every sale published on the brand''s own program panel, with a 60-day window; no cap statement, so the cap is unknown.", "contact_access": "Application runs through the brand''s Affiliatly program panel; no public partnerships email was published on the fetched page.", "credibility": "Established DTC seafood brand built on per-fish mercury testing; a smaller name than the national grocery brands.", "niche_fit": "Low-mercury tuna and clean seafood fit healthy-eating, pregnancy-nutrition, keto and pantry-staple creators well.", "opportunity_availability": "Program is live and joinable now through the program panel.", "ugc_evidence": "The program panel speaks directly to bloggers and social-media creators and offers codes, links and a follower discount."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Seed', 'https://seed.com', 'Seed is a science-led microbiome company selling the DS-01 Daily Synbiotic (probiotic + prebiotic) and related synbiotics by subscription, with an affiliate program that has historically run through ShareASale alongside its Seed University education platform.', 'United States', 'published') returning id into bid;
