  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Seed Affiliate Program', 'https://getlasso.co/affiliate/seed/', 'https://getlasso.co/affiliate/seed/', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://getlasso.co/affiliate/seed/', 'affiliate_directory', 'affiliate_program', 'Lasso''s Seed program page, fetched first-hand, lists a 15% per-sale commission with a 90-day cookie. Other published sources conflict: program roundups report a 25% base rate for affiliates via ShareASale (with a separate 100% partner-influencer track) and a 25% base with a 30-day cookie elsewhere. Because the published figures conflict and none is the brand''s own program page, commission_rate is null with the conflict documented. No earnings-cap statement is published, so commission_cap is unknown; no creator-count data is published, so creator_saturation is unknown.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 26, 14, 10, 6, 8, 5, '{"compensation": "Published figures conflict (15% vs 25% base), so the rate is honestly null; either figure would be a strong rate for a premium subscription product.", "contact_access": "Application runs through the program listing/network; no public partnerships email was verified on a fetched brand page.", "credibility": "One of the most established science-led probiotic brands, with clinically studied strains and a large research profile.", "niche_fit": "Premium gut-health synbiotics are a flagship fit for wellness, gut-health and science-focused creators.", "opportunity_availability": "Program is listed as live and joinable; approval typically takes a few days per the listing.", "ugc_evidence": "A long-running affiliate program with a creator education platform (Seed University) reported across multiple program sources."}'::jsonb);
