  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://support.sunbasket.com/hc/en-us/articles/40605896166547-Introducing-the-Sunbasket-Affiliate-Program', 'brand_website', 'affiliate_program', 'Sunbasket''s own support announcement of its affiliate program (April 2025), fetched first-hand, confirms the program is designed for influencers and content creators, health and wellness influencers among them, offers a competitive tiered commission structure with custom tracking links and dashboards, routes applications through its Everflow portal, and prints the Partnerships Team contact partners@sunbasket.com. The brand page publishes no percentage or bounty, and third-party figures conflict (an older ShareASale-era $20 per sale vs a $30 per new subscriber listing), so commission_rate is null with the conflict documented. No earnings-cap statement is published, so commission_cap is unknown; no creator-count data is published, so creator_saturation is unknown.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 25, 15, 9, 13, 9, 4, '{"compensation": "The brand publishes no rate on its own page and third-party bounty figures conflict ($20 vs $30), so the rate is honestly null until terms appear inside Everflow.", "contact_access": "A named Partnerships Team email, partners@sunbasket.com, is printed on the brand''s own program announcement \u2014 strong contact access.", "credibility": "Established national organic meal-kit brand; the 2025 program relaunch and unpublished rates cost a point.", "niche_fit": "Organic, diet-specific meal kits fit food, clean-eating and family-wellness creators very well.", "opportunity_availability": "The relaunched program is live and joinable now via the brand''s Everflow portal.", "ugc_evidence": "The brand''s own announcement explicitly recruits influencers and content creators, with creative assets and one-on-one affiliate support."}'::jsonb);
