  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.vitalchoice.com/v/affiliate-web-program', 'brand_website', 'affiliate_program', 'Vital Choice''s own affiliate page, fetched first-hand, publishes standard payouts of 4% for new customers and 1% for existing customers, plus a flat $15 payout for new Vital Box subscriptions (recorded as flat in this evidence; the 4% new-customer percentage rate is recorded), an average order value of $175+, and routes applications through the Impact Radius marketplace. No earnings-cap statement is published, so commission_cap is unknown; no creator-count data is published, so creator_saturation is unknown.', 'verified', now());
