  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://getlasso.co/affiliate/joybird/', 'listing', 'affiliate', 'Lasso''s Joybird program listing fetched: 15% per sale with a 60-day cookie, and the join link routes to FlexOffers. Multiple independent sources agree on the 15% figure (Bosshouz, 3hundrd, Buildapreneur and One More Cup of Coffee all report 15% via FlexOffers; PressLoft reports FlexOffers/VigLink). One source claims the program runs on Impact instead, so the network rests on the majority FlexOffers reporting and is documented here. No earnings-cap statement is published anywhere fetched, so the cap is unknown.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 25, 12, 14, 9, 8, 4, '{"compensation": "15% per sale with a long 60-day cookie on high-ticket furniture is strong pay; the rate is third-party reported (several sources agree) rather than brand-published, and no cap statement exists", "contact_access": "Application runs through the FlexOffers network listing; no direct affiliate email is published", "credibility": "Established national DTC furniture brand with a consistently reported program across independent listings", "niche_fit": "Furniture and home makeovers are a core home-content category \u2014 room reveals, sofa reviews and small-space styling are natural UGC", "opportunity_availability": "Open network application, subject to approval", "ugc_evidence": "A standing network program reported across many independent affiliate directories; no dedicated creator tier is published"}'::jsonb);
