  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Made In Affiliate Program — premium cookware via ShareASale; published reports conflict (8-12% / up to 12% / 15%), so the rate is unsettled', 'https://commissiondex.com/category/food-cooking/', 'https://commissiondex.com/category/food-cooking/', 'unverified', 'ugc');
