  insert into public.brands (name, website, description, country, status) values ('Pawstruck', 'https://pawstruck.com', 'Natural dog treats and chews brand — bully sticks, collagen sticks and long-lasting chews — sold through pawstruck.com. Its own affiliate page publishes a flat 10% commission, a free product of choice for affiliates, monthly PayPal payouts and the partnerships contact partners@pawstruck.com; the program is listed on ShareASale.', 'United States', 'published') returning id into bid;
