  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://bedjet.com/pages/affiliates', 'listing', 'affiliate', 'Rate reporting: Lasso reports 8% with a 60-day cookie, LinkClicky lists BedJet on CJ Affiliate at 8% as officially listed, and affiliate-toolkit also reports CJ at 8% — three sources agree, so the recorded 8% is marked publicly_reported. Shopper instead reports a generic 5-10% range, and a separate Refersion portal (bedjet.refersion.com) also exists; both are documented here. No earnings-cap statement is published, so the cap is unknown.', 'publicly_reported', now());
