  insert into public.brands (name, website, description, country, status) values ('Lofree', 'https://www.lofree.co', 'Retro-design mechanical keyboard and desk-accessory brand (the Flow and Dot keyboard lines) sold through lofree.co. Its own affiliate program page publishes a 5% standard commission on all products, a 30-day cookie and average order value of $150-$200, with signup routed to CJ Affiliate and the contact marketing@lofree.co.', 'China', 'published') returning id into bid;
