  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.lofree.co/pages/affiliate-program', 'official_site', 'affiliate', 'Lofree''s own affiliate program page fetched in full: 5% standard commission on all products, a 30-day cookie, average order value of $150-$200, free to join, payments issued on the 20th of each month, and the published contact marketing@lofree.co. The page''s Start Now button links to CJ signup (public.cj.com), yet one FAQ asks ''What should I do if I can''t use Sharesale?'' — a network inconsistency on the brand''s own page, documented here; the recorded network is CJ Affiliate per the live signup link. Lasso''s ''up to 11.25%'' figure is a Lasso marketplace number, not the program rate. No earnings-cap statement is published, so the cap is unknown.', 'verified', now());
