  insert into public.brands (name, website, description, country, status) values ('Neewer', 'https://neewer.com', 'Photography and videography equipment brand — LED video lights, tripods, ring lights and studio gear — sold through neewer.com. Its own affiliate program page explicitly welcomes content creators, photographers and videographers, offers up to 10% commission with monthly performance bonuses, and routes signup to the brand''s GoAffPro portal.', 'China', 'published') returning id into bid;
