  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Brand direct', null, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://neewer.com/pages/affiliate-program.', 'https://neewer.com/pages/affiliate-program', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Neewer Affiliate Program — creator gear via the brand''s own GoAffPro portal; page publishes up to 10% plus monthly performance bonuses (tiered reports, so the rate is unsettled), 30-day cookie', 'https://neewer.com/pages/affiliate-program', 'https://neewer.com/pages/affiliate-program', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://neewer.com/pages/affiliate-program', 'official_site', 'affiliate', 'Neewer''s own affiliate program page fetched in full: ''We welcome creative individuals and content platforms passionate about photography and videography to join our affiliate program'', offering ''Up to 10% commission for every purchase'' plus extra bonuses for monthly performance, an industry-leading 30-day cookie, free to join, commissions processed within 30 days after the end of the month, and a $100 minimum withdrawal amount. Signup routes to the brand''s own portal (neewer.goaffpro.com). An ''up to 10%'' figure is a rate ceiling, and a third-party report (RushRadar) describes tiers of 6% standard / 8% over $10K / 10% over $50K in monthly sales, so no single rate is settled and commission_rate is null with the structure documented here. No earnings-cap statement is published, so the cap is unknown.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 25, 14, 11, 10, 9, 4, '{"compensation": "Up to 10% plus monthly performance bonuses on creator gear is attractive, but the published figure is a ceiling with tiered third-party reports, so compensation is scored on unsettled evidence; no cap statement exists", "contact_access": "Application via the brand''s own affiliate portal from the official program page; no direct affiliate email is published", "credibility": "Globally recognized photography-equipment brand with a complete, terms-published program page", "niche_fit": "Video lights, tripods and ring lights are the tools creator audiences buy \u2014 gear reviews, lighting setups and studio tours are natural UGC", "opportunity_availability": "Free to join through the brand''s own portal", "ugc_evidence": "The brand''s own page explicitly recruits content creators, photographers and videographers \u2014 direct creator-facing program evidence"}'::jsonb);
